"""Build the local review gallery from the source manifest, without duplicating photos."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parent
original=[{'id':'home','alt':'树荫下的校园建筑','category':'原有照片','preview':'/src/assets/campus/home-background.jpg'},{'id':'evening','alt':'黄昏时的校园与水面','category':'原有照片','preview':'/src/assets/campus/evening-campus.jpg'},{'id':'courtyard','alt':'校园公共空间与建筑','category':'原有照片','preview':'/src/assets/campus/campus-services.jpg'}]
items=json.loads((OUT/'sources.json').read_text(encoding='utf-8'))['selected']+original
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>会同里 · 校园影集</title><style>
@font-face{font-family:MiSans;src:url('/fonts/misans/MiSans-Regular.woff2')}@font-face{font-family:WenKai;src:url('/fonts/lxgw-wenkai/BNBUWenKai-Medium.woff2')}*{box-sizing:border-box}body{margin:0;background:#faf9f6;color:#263b40;font-family:MiSans,'Microsoft YaHei',sans-serif}main{max-width:1340px;margin:auto;padding:36px 32px}header{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:28px}h1{font:500 38px/1.4 WenKai,serif;margin:0 0 8px}p{font-size:15px;line-height:1.8;color:#5b6c62;margin:0}a{color:#426575}header a{padding:12px 18px;border:1px solid #dbe2d8;border-radius:6px;text-decoration:none;white-space:nowrap}nav{display:flex;gap:10px;overflow:auto;margin-bottom:24px;padding-bottom:6px}button{font:inherit;cursor:pointer;color:inherit}nav button{white-space:nowrap;min-height:44px;padding:8px 18px;background:transparent;border:1px solid #dce3d8;border-radius:24px}nav button[aria-pressed=true]{background:#426575;color:#fff;border-color:#426575}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px 22px}.grid article{min-width:0}.photo{padding:0;border:0;background:#e8ece5;width:100%;aspect-ratio:3/2;display:block;overflow:hidden;border-radius:5px}.photo img{display:block;width:100%;height:100%;object-fit:cover}.caption{display:flex;justify-content:space-between;gap:10px;margin:12px 0 5px}.caption strong{font-weight:500;font-size:16px}.caption span{font-size:13px;color:#5b6c62;white-space:nowrap}.grid small{color:#5b6c62;font-size:12px}footer{margin:36px 0 0;padding-top:20px;border-top:1px solid #dce3d8;line-height:1.9;color:#5b6c62;font-size:13px}dialog{padding:16px;border:1px solid #dbe2d8;border-radius:6px;background:#faf9f6;max-width:min(1100px,94vw);max-height:94vh}dialog::backdrop{background:#172c34cc}.full{display:block;max-width:100%;max-height:72vh;width:auto;height:auto;object-fit:contain}.viewer-tools{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-top:12px}.viewer-tools button{min-width:44px;min-height:44px;border:1px solid #dce3d8;border-radius:4px;background:#fffefa}.viewer-tools span{flex:1;text-align:center;font-size:14px}button:focus-visible,a:focus-visible{outline:3px solid #426575;outline-offset:3px}[hidden]{display:none!important}@media(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){main{padding:24px 20px}header{align-items:flex-start;flex-direction:column;gap:16px}h1{font-size:32px}.grid{grid-template-columns:1fr;gap:24px}.viewer-tools span{font-size:12px}footer{font-size:12px}}@media(hover:hover) and (prefers-reduced-motion:no-preference){.photo img{transition:transform .3s ease}.photo:hover img{transform:scale(1.025)}}
</style><main><header><div><h1>在校园，多看一眼。</h1><p>12 张校园实景 · 本次新增 9 张 · 点击照片查看完整画幅</p></div><a href="/v2">打开学生首页 ↗</a></header><nav aria-label="照片分类"></nav><section class="grid" aria-label="校园照片"></section><footer>新增照片来源：<a href="https://www.bnbu.edu.cn/info/1058/17244.htm" target="_blank" rel="noopener">北师香港浸会大学官网 · 校园风光</a>。原有三张沿用项目素材。<br>本地设计预览；新增照片版权归原权利人，来源记录不构成开放许可或对外发布授权。</footer></main><dialog aria-label="校园照片完整画幅"><img class="full" alt=""><div class="viewer-tools"><button id="prev" aria-label="上一张">←</button><span></span><button id="next" aria-label="下一张">→</button><button id="close" aria-label="关闭照片">×</button></div></dialog><script>
const photos=PHOTOS;const grid=document.querySelector('.grid'),nav=document.querySelector('nav'),dialog=document.querySelector('dialog');let active=0;['全部',...new Set(photos.map(p=>p.category))].forEach((category,i)=>{const b=document.createElement('button');b.textContent=category;b.setAttribute('aria-pressed',i===0);b.onclick=()=>{nav.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));grid.querySelectorAll('article').forEach((a,j)=>a.hidden=category!=='全部'&&photos[j].category!==category)};nav.append(b)});photos.forEach((p,i)=>{const article=document.createElement('article');const button=document.createElement('button');button.className='photo';button.setAttribute('aria-label','查看'+p.alt);const image=document.createElement('img');image.src=p.preview;image.alt=p.alt;image.loading='lazy';image.decoding='async';image.style.objectPosition=p.position||'center';button.append(image);button.onclick=()=>{show(i);dialog.showModal()};const caption=document.createElement('div');caption.className='caption';const title=document.createElement('strong');title.textContent=p.alt;const tag=document.createElement('span');tag.textContent=p.category;caption.append(title,tag);const small=document.createElement('small');small.textContent=p.width?p.width+' × '+p.height+' · 官网实景':'项目原有素材';article.append(button,caption,small);grid.append(article)});function show(i){active=(i+photos.length)%photos.length;const p=photos[active];dialog.querySelector('img').src=p.preview;dialog.querySelector('img').alt=p.alt;dialog.querySelector('span').textContent=(active+1)+' / '+photos.length+' · '+p.alt}document.querySelector('#prev').onclick=()=>show(active-1);document.querySelector('#next').onclick=()=>show(active+1);document.querySelector('#close').onclick=()=>dialog.close();dialog.onkeydown=e=>{if(e.key==='ArrowLeft')show(active-1);if(e.key==='ArrowRight')show(active+1)};</script></html>'''.replace('PHOTOS',json.dumps(items,ensure_ascii=False))
(OUT/'index.html').write_text(html,encoding='utf-8');print('Campus photo gallery: '+str(len(items)))
